package wailsapp

import "encoding/base64"

// The Wails build generator consumes desktop/assets/appicon.svg and emits the
// platform application icons. Tray images are embedded here because desktop
// application bundles do not have a stable process working directory.
const (
	trayIconBase64     = ""
	trayTemplateBase64 = ""
)

func trayIconBytes() []byte         { return decodeAsset(trayIconBase64) }
func trayTemplateIconBytes() []byte { return decodeAsset(trayTemplateBase64) }

func decodeAsset(encoded string) []byte {
	data, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil {
		panic(err)
	}
	return data
}
